// Nettoyage avant découpage, document par document : bibliographie, appels de référence, césures.
// Le texte arrive page par page (Extract from File, joinPages: false). Les pages vidées sont ignorées par le nœud suivant.
const TITRE_BIBLIO = /^[ \t]*(references|bibliography|références|bibliographie)[ \t]*$/gim;
const FIN_BIBLIO = /^[ \t]*(Table|Figure)\b/m;  // manuscrits PMC : tableaux et figures placés après les références
const MARQUEURS_BIBLIO = /et al\.|doi|\((?:19|20)\d{2}\)/g;  // plus de 3 pour 1 000 caractères : page de références
const LIGNE_APPEL = /^[ \t]*\d{1,3}(?:[ \t]*[,–-][ \t]*\d{1,3})*[ \t]*$/;  // pdf.js met chaque exposant sur sa propre ligne
const APPEL_CROCHETS = /[ \t]?\[\d{1,3}(?:[ \t]*[,–-][ \t]*\d{1,3})*\]/g;
const CESURE = /([A-Za-z]+)-[ \t]*\n[ \t]*([a-z]+)/g;

function couperBibliographie(pages) {
  // 1. Titre « References » : dernière occurrence, seulement dans la seconde moitié du document (pas une table des matières).
  const total = pages.join('').length;
  let cumul = 0, coupe = null;
  pages.forEach((p, i) => {
    for (const m of p.matchAll(TITRE_BIBLIO)) if (cumul + m.index > total / 2) coupe = { page: i, pos: m.index };
    cumul += p.length;
  });
  // La bibliographie s'arrête au premier tableau ou à la première figure qui la suit, sinon à la fin du document.
  for (let i = coupe ? coupe.page : pages.length; i < pages.length; i++) {
    const debut = i === coupe.page ? coupe.pos : 0;
    const fin = pages[i].slice(debut).search(FIN_BIBLIO);
    pages[i] = pages[i].slice(0, debut) + (fin >= 0 ? pages[i].slice(debut + fin) : '');
    if (fin >= 0) break;
  }
  // 2. Notes de fin sans titre (ex. D06) : pages finales où les marqueurs bibliographiques sont denses.
  for (let i = pages.length - 1; i >= 0; i--) {
    if (!pages[i].trim()) continue;
    if (((pages[i].match(MARQUEURS_BIBLIO) || []).length * 1000) / pages[i].length < 3) break;
    pages[i] = '';
  }
  return pages;
}

function retirerAppels(page, stats) {
  const lignes = [];
  for (const ligne of page.split('\n')) {
    if (lignes.length && LIGNE_APPEL.test(ligne)) {
      const prec = lignes[lignes.length - 1];
      // Indice ou exposant d'un symbole (kg/m2, K1, n1) : recollé au symbole au lieu d'être supprimé.
      if (/(^|\s)[A-Za-z\/]{1,4}$/.test(prec) && /^\s*\d\s*$/.test(ligne)) lignes[lignes.length - 1] = prec + ligne.trim();
      else stats.appels++;
      continue;
    }
    lignes.push(ligne);
  }
  const texte = lignes.join('\n');
  stats.appels += (texte.match(APPEL_CROCHETS) || []).length;
  return texte.replace(APPEL_CROCHETS, '');
}

return $input.all().map((item, i) => {
  const brut = item.json.text;
  const stats = { caracteres_avant: brut.join('').length, bibliographie: 0, appels: 0, cesures: 0 };
  let pages = couperBibliographie([...brut]);
  stats.bibliographie = stats.caracteres_avant - pages.join('').length;
  // Césure en fin de ligne : on recolle seulement si le mot entier existe ailleurs dans le document ;
  // sinon c'est un mot composé (machine-learning, non-hypertensive) et le trait d'union est gardé.
  const vocabulaire = new Set(pages.join('\n').toLowerCase().match(/[a-z]+/g));
  pages = pages.map((p) => retirerAppels(p, stats).replace(CESURE, (m, a, b) => {
    if (!vocabulaire.has((a + b).toLowerCase())) return `${a}-${b}`;
    stats.cesures++;
    return a + b;
  }));
  stats.caracteres_apres = pages.join('').length;
  return { json: { ...item.json, text: pages, nettoyage: stats }, pairedItem: i };
});

// Une page = un item, avec les métadonnées du document (meta.json) et le numéro de page.
const pages = [];
for (const [i, item] of $input.all().entries()) {
  const meta = $('Un item par document').itemMatching(i).json;
  item.json.text.forEach((texte, p) => {
    if (texte.trim()) pages.push({ json: { ...meta, page: p + 1, texte } });
  });
}
return pages;
